DROP TABLE IF EXISTS `fips`;
CREATE TABLE `fips` (
  `RIIL` double default NULL,
  `NO` varchar(255) default NULL,
  `NM` varchar(255) default NULL,
  `KAT` varchar(255) default NULL,
  `KORP` varchar(255) default NULL,
  `NRP` varchar(255) default NULL,
  `JAB` varchar(255) default NULL,
  `AGAMA` varchar(255) default NULL,
  `K_TK` varchar(255) default NULL,
  `JANAK` double default NULL,
  `TGLHR` varchar(255) default NULL,
  `TPTLHR` varchar(255) default NULL,
  `DIKMIL` varchar(255) default NULL,
  `DIKUM` varchar(255) default NULL,
  `ALAMAT` varchar(255) default NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
